def luhn_valid(s):
    s = ''.join(c for c in s if c.isdigit())
    n = len(s)
    if n < 2:
        return False
    sum = 0
    for i in range(n - 1, -1, -2):
        digit = int(s[i])
        if i % 2 == 0:
            digit *= 2
            if digit > 9:
                digit -= 9
        sum += digit
    return sum % 10 == 0
```

