def parse_duration(s):
    parts = s.split()
    if len(parts) == 1 and not parts[0]:
        return None
    total_seconds = 0
    for i, part in enumerate(parts):
        if i == 0:
            hours = int(part)
        elif i == 1:
            minutes = int(part)
        else:
            seconds = int(part)
        total_seconds += hours * 3600 + minutes * 60 + seconds
    return total_seconds
```

