def title_case(s):
    if not s:
        return ""

    words = s.split()
    result = []
    for word in words:
        if word.lower() in ["a", "the", "of", "and", "but", "or", "on", "in"]:
            result.append(word.lower())
        else:
            result.append(word.capitalize())

    return ' '.join(result)
```

